<script module lang="ts">
/**
 * RichTextContent.Item: a list’s item and its drawn blocks.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext } from 'svelte'

import {
  attributes,
  joinSlot,
  richTextPositionAttrs,
  type RichTextDrawnBlock,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import CodeBlock from './CodeBlock.svelte'
import Heading from './Heading.svelte'
import RichTextContentBlocks from './RichTextContentBlocks.svelte'
import RichTextContentInlines from './RichTextContentInlines.svelte'
import RichTextContentItem from './RichTextContentItem.svelte'
import Text from './Text.svelte'

export interface RichTextContentItemProps {
  blocks: RichTextDrawnBlock[]
}
</script>

<script lang="ts">
let { blocks }: RichTextContentItemProps = $props()
const joined = joinSlot(undefined, () => ({}))
const owner: Record<string, any> = getContext('polymorph:RichTextContent') ?? {}
</script>

{@render joined.start?.()
}{#if joined.shown
  }<li class={styles.item}
    >{#each blocks as block, index (index)
      }{#if block.kind === 'paragraph'
        }<Text size={owner.size}><RichTextContentInlines inlines={block.inlines} /></Text
      >{:else if block.kind === 'heading'
        }<Heading level={block.level}>{block.text}</Heading
      >{:else if block.kind === 'ownHeading' && block.level === 4
        }<h4 class={styles.heading} data-level={String(block.level)}
          ><RichTextContentInlines inlines={block.inlines}
        /></h4
      >{:else if block.kind === 'ownHeading' && block.level === 3
        }<h3 class={styles.heading} data-level={String(block.level)}
          ><RichTextContentInlines inlines={block.inlines}
        /></h3
      >{:else if block.kind === 'ownHeading'
        }<h2 class={styles.heading} data-level={String(block.level)}
          ><RichTextContentInlines inlines={block.inlines}
        /></h2
      >{:else if block.kind === 'list' && block.ordered
        }<ol class={styles.list} start={block.start}
          >{#each block.items as entry, position (position)
            }<RichTextContentItem blocks={entry}
          />{/each
        }</ol
      >{:else if block.kind === 'list'
        }<ul class={styles.list}
          >{#each block.items as entry, position (position)
            }<RichTextContentItem blocks={entry}
          />{/each
        }</ul
      >{:else if block.kind === 'quote'
        }<blockquote class={styles.quote}
          ><RichTextContentBlocks blocks={block.blocks}
        /></blockquote
      >{:else if block.kind === 'codeBlock' && block.at === null
        }<CodeBlock copyable={block.copyable} label={block.language}>{block.text}</CodeBlock
      >{:else if block.kind === 'codeBlock'
        }<div {...attributes(richTextPositionAttrs(block.at, true, true))}
          ><CodeBlock copyable={block.copyable} label={block.language}>{block.text}</CodeBlock
        ></div
      >{:else if block.kind === 'later' && block.at === null
        }<Text size={owner.size}>{block.text}</Text
      >{:else if block.kind === 'later'
        }<Text size={owner.size}
          ><span {...attributes(richTextPositionAttrs(block.at, true))}>{block.text}</span
        ></Text
      >{/if
    }{/each
  }</li
>{/if
}{@render joined.end?.()}
